#!/usr/bin/env python3
"""PreToolUse hook: block hand edits to generated files (data and the Xcode project) in any checkout or worktree."""
import json, pathlib, sys

GENERATED = {
    'Core/Resources/': 'is generated by Scripts/import_osm.py; change the importer and rerun it (data-pipeline skill)',
    'Data/provenance.json': 'is generated by Scripts/import_osm.py',
    'Peoplemaps.xcodeproj/': 'is generated by Scripts/generate_project.py; change the generator and rerun it',
}
tool_input = json.load(sys.stdin).get('tool_input', {})
path = pathlib.Path(tool_input.get('file_path') or tool_input.get('notebook_path') or '').resolve()
# The checkout root is the nearest folder holding Package.swift, so worktrees are covered too.
root = next((p for p in path.parents if (p / 'Package.swift').exists()), None)
if root:
    relative = path.relative_to(root).as_posix()
    for prefix, why in GENERATED.items():
        if relative.startswith(prefix):
            print(f'{relative} {why}.', file=sys.stderr)
            sys.exit(2)
